"""Assemble rendered evidence into a local review page, sheet and silent MP4."""
import json,subprocess,html
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import imageio_ffmpeg
root=Path(__file__).resolve().parents[1];out=root/'ilustrasi/avatar-v2/farmer-v12-expression'
test=json.loads((out/'expression-test.json').read_text());wardrobe=json.loads((out/'runtime-test.json').read_text())
ffmpeg=imageio_ffmpeg.get_ffmpeg_exe()
subprocess.run([ffmpeg,'-y','-loglevel','error','-framerate','12','-i',str(out/'demo-frames/%03d.png'),'-c:v','libx264','-pix_fmt','yuv420p','-crf','20','-movflags','+faststart',str(out/'expression-demo.mp4')],check=True)
font=ImageFont.truetype('C:/Windows/Fonts/segoeui.ttf',25)
sheet=Image.new('RGB',(1200,840),'#f4f0e8');draw=ImageDraw.Draw(sheet)
for i,(name,label) in enumerate([('baseline-face','V11 / sebelumnya'),('face','V12 / kandidat')]):
 im=Image.open(out/(name+'.png')).convert('RGB');im.thumbnail((580,760));sheet.paste(im,(i*600+(600-im.width)//2,65))
 draw.text((i*600+22,18),label,font=font,fill='#243b35')
sheet.save(out/'comparison.jpg',quality=94)
expressions=[('face','Netral'),('smile','Senang'),('angry','Kesal'),('sad','Sedih'),('surprised','Terkejut'),('blink','Kedip')]
def cards(items):
 return ''.join(f'<figure><img loading="lazy" src="{name}.png" alt="{label}"><figcaption>{label}</figcaption></figure>' for name,label in items)
